def PolynomialThinning (P : ClampLaw J) (kappa cminus cplus : ℝ) : Prop :=
  ∀ x : Fin J, ∀ᵐ a ∂volume.restrict (Set.Icc (0 : ℝ) 1),
    cminus * a ^ kappa ≤ P.pi x a ∧ P.pi x a ≤ cplus * a ^ kappa

