/-- Uniform population-Gram constant. -/
def lambdaStar (ell : ℕ) (kappa cminus cplus : ℝ) : ℝ :=
  (cminus / cplus) * sInf {q : ℝ | ∃ rho : ℝ, 0 ≤ rho ∧
    q = quadraticMin (refMomentMatrix ell kappa rho)}

