/-- Monomial basis `(1,u,...,u^ell)`. -/
def monomialVec (ell : ℕ) (u : ℝ) : Fin (ell + 1) → ℝ :=
  fun j => u ^ (j : ℕ) -- @realizes v_ell(monomial basis through degree ell)

